import {predictHousehold} from './ml-model.js';
let model=null,evaluation=null,clusters=null,profile={},current=null,context=null,apply=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(x,d=1)=>x!==null&&x!==undefined&&Number.isFinite(Number(x))?Number(x).toLocaleString('en-US',{maximumFractionDigits:d}):'—';
const metric=(obj,...keys)=>{for(const k of keys){const v=k.split('.').reduce((a,b)=>a?.[b],obj);if(v!==undefined&&v!==null)return v;}return null;};
const $=s=>document.querySelector(s);
const q=x=>x!==null&&x!==undefined&&Number.isFinite(Number(x))?Number(x):null;
export async function initAILab(options){apply=options.onApply;context=options.getContext;const read=async name=>{const r=await fetch('./data/'+name);if(!r.ok)return null;return r.json();};[model,evaluation,clusters]=await Promise.all([read('ml-model.json'),read('ml-evaluation.json'),read('site-clusters.json')]);if(model)predict();return {ready:!!model,modelId:model?.model_id};}
function predict(){if(!model)return null;try{current=predictHousehold(profile,model);return current;}catch(e){current={error:e.message};return current;}}
function values(){const all=evaluation||{},models=all.models||{};const rf=metric(all,'models.random_forest.test','models.random_forest','random_forest.test','random_forest')||{};const baseline=metric(all,'models.median_baseline.test','models.median_baseline','baseline.test','baseline')||{};const con=all.conformal||all.calibration||{};return {rf,baseline,mae:q(metric(rf,'mae','MAE')),baseMae:q(metric(baseline,'mae','MAE')),coverage:q(metric(con,'test_coverage','empirical_coverage','coverage')),width:q(metric(con,'mean_width','mean_interval_width','test_mean_width')),train:metric(all,'split.train.households','split.train','split.n_train','splits.train','sample_sizes.train'),cal:metric(all,'split.calibration.households','split.calibration','split.n_calibration','splits.calibration','sample_sizes.calibration'),test:metric(all,'split.test.households','split.test','split.n_test','splits.test','sample_sizes.test')};}
function detailsMetrics(){const v=values();const split=model?.split||{};return '<div class="ai-metrics"><div><span>Held-out MAE · household proxy</span><strong>'+n(v.mae)+' <small>kWh/month</small></strong><p>Lower is better · historical survey domain</p></div><div><span>Median baseline MAE</span><strong>'+n(v.baseMae)+' <small>kWh/month</small></strong><p>Simple benchmark on the same test households</p></div><div><span>90% interval · test coverage</span><strong>'+(v.coverage===null?'—':n(v.coverage*100))+'<small>%</small></strong><p>Empirical coverage · '+n(v.width)+' kWh mean width</p></div></div>';}
function form(){return '<div class="ai-profile-grid">'+model.feature_schema.map(f=>{const value=Object.hasOwn(profile,f.name)?profile[f.name]:f.default;const entered=Object.hasOwn(profile,f.name);const field=Array.isArray(f.options)&&f.options.length?'<select id="ml-'+esc(f.name)+'" data-ml-feature="'+esc(f.name)+'">'+f.options.map(o=>'<option value="'+esc(o.value)+'" '+(Number(o.value)===Number(value)?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select>':'<input id="ml-'+esc(f.name)+'" data-ml-feature="'+esc(f.name)+'" type="number" min="'+esc(f.physical_min??f.min??0)+'" max="'+esc(f.physical_max??f.max??100)+'" step="any" value="'+esc(value)+'">';return '<div class="field"><label for="ml-'+esc(f.name)+'">'+esc(f.label)+'<span class="ai-assumed">'+(entered?'Scenario input':'Training default')+'</span></label>'+field+'</div>';}).join('')+'</div>';}
function humanFlag(flag){if(typeof flag!=='string')return 'Input quality note';const known={survey_proxy_not_metered:'Consumption is survey-derived, not metered.',geographic_transfer_unvalidated:'Performance outside the survey sample is unverified.',northern_region_is_not_lamwo_validation:'A Northern region profile does not establish Lamwo accuracy.'};if(known[flag])return known[flag];if(flag.startsWith('imputed_')){const name=flag.slice(8);return (model.feature_schema.find(f=>f.name===name)?.label||'Profile input')+': using a training default.';}return flag.replaceAll('_',' ');}
function predictionCard(){if(!current||current.error)return '<p class="validation-note">'+esc(current?.error||'Model is not ready.')+'</p>';const lower=current.lower??current.interval?.lower,upper=current.upper??current.interval?.upper;const flags=current.flags||[];return '<div class="ai-prediction"><div class="eyebrow">TRAINED HOUSEHOLD MODEL</div><h3>'+n(current.prediction)+' <span>kWh / household / month</span></h3><div class="ai-interval"><div><span>Lower</span><strong>'+n(lower)+'</strong></div><div class="ai-interval-line"></div><div><span>Upper</span><strong>'+n(upper)+'</strong></div></div><p>90% split-conformal residual interval for this historical survey target. Coverage on future mini-grid sites has not been established.</p><button class="btn lime" data-ai-action="apply">Use as a household scenario →</button><p class="ai-small">This changes the planner’s household energy input. It does not transfer the household interval to village totals.</p></div><div class="ai-flags">'+flags.slice(0,8).map(f=>'<span>'+esc(humanFlag(f))+'</span>').join('')+'</div>';}
function importanceMarkup(){if(!current||current.error)return '';let drivers=current.drivers||[];if(!drivers.length&&model.model?.feature_importances)drivers=model.feature_schema.map((f,i)=>({label:f.label,importance:model.model.feature_importances[i]}));return '<div class="ai-importance">'+drivers.slice().sort((a,b)=>b.importance-a.importance).slice(0,7).map(d=>'<div><span>'+esc(d.label||d.feature)+'</span><div class="ai-bar"><i style="width:'+Math.max(0,Math.min(100,(Number(d.importance)||0)*100))+'%"></i></div><strong>'+n((Number(d.importance)||0)*100)+'%</strong></div>').join('')+'</div><p class="chart-caption">Global forest feature importance describes model usage across training data. It is not a local explanation or a causal effect.</p>';}
function sensitivityMarkup(){if(!current||current.error)return '';const candidates=[];for(const f of model.feature_schema){const vals=f.options?.length?f.options.map(o=>o.value):[f.min,f.max].filter(x=>Number.isFinite(Number(x)));if(vals.length<2)continue;const base={...current.inputs};let out=[];for(const v of vals){try{const r=predictHousehold({...base,[f.name]:v},model);if(Number.isFinite(r.prediction))out.push(r.prediction);}catch{}}if(out.length>1)candidates.push({feature:f.name,label:f.label,spread:Math.max(...out)-Math.min(...out),assumed:!Object.hasOwn(profile,f.name)});}candidates.sort((a,b)=>b.spread-a.spread);return '<div class="ai-priorities">'+candidates.slice(0,3).map((c,i)=>'<div><b>0'+(i+1)+'</b><div><strong>'+esc(c.label)+'</strong><p>'+n(c.spread)+' kWh/month variation across observed training-domain values · '+(c.assumed?'currently a training default':'scenario input')+'</p></div></div>').join('')+'</div><p class="chart-caption">One-at-a-time profile sensitivity helps prioritize questions. These combinations may not be observed together; this is not a causal estimate or a prediction of accuracy gained from a survey.</p>';}
function clusterMarkup(){if(!clusters)return '<p class="info-note">Settlement archetype training is not available in this build.</p>';const s=context?.().site,assignment=clusters.assignments?.[String(s?.id)];const cid=typeof assignment==='object'?assignment.cluster_id??assignment.cluster:assignment;const all=clusters.clusters||[];return '<div class="ai-clusters">'+all.map(c=>'<article class="'+(String(c.id)===String(cid)?'selected':'')+'"><span class="head-tag">Cluster '+(Number(c.id)+1)+' · '+n(c.size,0)+' villages</span><h3>'+esc(c.size<5?'Context outlier':c.label||'Settlement archetype')+'</h3><p>'+esc(c.size<5?'A sparse group: inspect source features before generalizing.':c.description||'Grouped by observed geographic characteristics.')+'</p><div class="ai-cluster-facts">'+Object.entries(c.summary||{}).slice(0,4).map(([k,v])=>'<span>'+esc(k.replaceAll('_',' '))+'<strong>'+n(v)+'</strong></span>').join('')+'</div>'+(String(c.id)===String(cid)?'<div class="ai-current">Current village: '+esc(s?.name)+'</div>':'')+'</article>').join('')+'</div><p class="chart-caption">Unsupervised grouping of geographic features. Archetypes are descriptive; they are not energy-demand labels or validated business opportunities.</p>';}
export function renderAILab(){if(!model)return '<section class="panel empty"><h2>The trained model is not loaded.</h2><p>Generate the model with scripts/train_model.py, then reload the app.</p></section>';const v=values();return '<section class="ai-intro"><div><div class="eyebrow">FIT. HOLD OUT. EXPLAIN.</div><h2>AI you can inspect.</h2><p>A real trained household model, an untouched evaluation set, and geographic archetypes. Every result carries its scope.</p></div><span class="ai-model-id">'+esc(model.model_id)+'</span></section>'+detailsMetrics()+'<div class="ai-layout"><section class="panel"><div class="panel-head"><div><h2>Build a household profile</h2><p class="subtext">Values are scenario assumptions; they are not inferred from the selected village.</p></div><button class="btn" data-ai-action="reset">Reset</button></div><div class="ai-profile-body">'+form()+'<div class="info-note">The model learns a payment-derived consumption proxy from 2019/2020 Uganda survey households. Power availability means the supply-hours scenario you enter. Housing and location associations do not establish causal effects.</div></div></section><aside id="ai-prediction-wrap">'+predictionCard()+'</aside></div><div class="charts-row"><section class="panel"><div class="panel-head"><h2>What the forest pays attention to</h2><span class="head-tag">Global importance</span></div><div class="chart-body" id="ai-importance">'+importanceMarkup()+'</div></section><section class="panel"><div class="panel-head"><h2>Which assumption should we check next?</h2><span class="head-tag">Profile sensitivity</span></div><div class="chart-body" id="ai-sensitivity">'+sensitivityMarkup()+'</div></section></div><section class="panel ai-archetypes"><div class="panel-head"><div><h2>Different settlements. Different starting points.</h2><p class="subtext">Geographic archetypes learned from 411 real villages</p></div><span class="head-tag">'+esc(clusters?.algorithm||'Unsupervised clustering')+'</span></div>'+clusterMarkup()+'</section><section class="panel ai-evaluation"><div class="panel-head"><div><h2>The evaluation ledger</h2><p class="subtext">Training, calibration and test households stay separate.</p></div><button class="btn" data-ai-action="download">Download model card & metrics</button></div><div class="ai-ledger"><div><span>Training households</span><strong>'+n(v.train,0)+'</strong></div><div><span>Calibration households</span><strong>'+n(v.cal,0)+'</strong></div><div><span>Untouched test households</span><strong>'+n(v.test,0)+'</strong></div><div><span>Metered mini-grid test sites</span><strong>0</strong></div></div><div id="ai-verdict" class="info-note">'+(v.mae!==null&&v.baseMae!==null?(v.mae<v.baseMae?'On this held-out survey sample, the forest has lower MAE than the median benchmark.':'The forest does not improve held-out MAE over the median benchmark. That result is retained; use the simpler benchmark where appropriate.'):'Held-out results are reported in the downloadable evaluation ledger.')+' Household-level historical validation does not establish site-level forecast accuracy in Lamwo.</div><div class="ai-bias-note"><strong>Bias matters:</strong> mean prediction minus observed is '+n(evaluation.test?.selected?.bias)+' kWh/month. This model underpredicts the held-out sample on average. Rural test results use only '+n(evaluation.test?.rural_descriptive?.n,0)+' households. Nominal 90% intervals covered '+n((evaluation.conformal?.test_coverage||0)*100)+'% on the test set.</div><p class="chart-caption">Imputation and encoding are fitted within training folds. Calibration uses held-out household residuals with a finite-sample quantile; final test households are not used for fitting or selection. Tariff uncertainty and geographic/domain shift are outside this residual calibration.</p></section><div class="validation-note"><strong>Deployment gate:</strong> use this as a transparent research and planning aid. Operator meter data, held-out site evaluation, growth validation and geographic transfer tests are required before a field decision product.</div>';}
function update(){predict();if($('#ai-prediction-wrap'))$('#ai-prediction-wrap').innerHTML=predictionCard();if($('#ai-importance'))$('#ai-importance').innerHTML=importanceMarkup();if($('#ai-sensitivity'))$('#ai-sensitivity').innerHTML=sensitivityMarkup();}
function handleProfileInput(e){const key=e.target.dataset.mlFeature;if(!key)return;const value=e.target.value;if(value===''||!Number.isFinite(Number(value))){e.target.value=current?.inputs?.[key]??model.feature_schema.find(f=>f.name===key)?.default;return;}profile[key]=Number(value);update();const clean=current?.inputs?.[key];if(clean!==undefined&&e.type==='change')e.target.value=clean;const label=e.target.closest('.field')?.querySelector('.ai-assumed');if(label)label.textContent='Scenario input';}
document.addEventListener('input',handleProfileInput);document.addEventListener('change',handleProfileInput);
document.addEventListener('click',e=>{const b=e.target.closest('[data-ai-action]');if(!b)return;const action=b.dataset.aiAction;if(action==='apply'&&current&&!current.error&&Number.isFinite(current.prediction))apply?.({value:current.prediction,model_id:model.model_id,features:current.inputs,interval:{lower:current.lower,upper:current.upper},flags:current.flags});if(action==='reset'){profile={};predict();const view=$('#view-content');if(view)view.innerHTML=renderAILab();}if(action==='download'){const payload={model_id:model.model_id,target:model.target,feature_schema:model.feature_schema,calibration:model.calibration,limitations:model.limitations,evaluation,geospatialModel:clusters};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='AimEnergy-ML-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);}});
export function getMLEvidence(){return {model_id:model?.model_id,feature_schema:model?.feature_schema,target:model?.target,calibration:model?.calibration,evaluation,profile,current};}
